-- GENERATED by `wfj generate` from data/quest/quest-0093.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [93036] = { "教団への潜入", "Shen'dar VillageのSania Silverstreamと話してください。", "知っているかどうか分からないが、あそこにいるSania Silverstreamは、Al'Akethの「宣教師」だ。奴らは普通の宗教団体のふりをして、害のなさそうな使者をあちこちに送って勧誘するのが好きなんだ。教団との直接の衝突を避けるため、これまでSaniaを大目に見てきたが、見せかけの平和がもう長くは続かないのは明らかだ。\n\n君はここに来たばかりで、ほとんどの者に知られていない。だから、君がSaniaを使って教団に近づき、奴らが村に対して何を企んでいるのか探れないか試してみたい。", nil, nil, 0xbb1fd4b2, 0x82bd3020, 0x16bf081e, nil, nil, "..smm" },
  [93065] = { "戦いへの備え", "Gustberry LowlandsのValennia Stormfistと話してください。", "Peacekeepersが動員され、我々は皆出発の準備を整えている。必要な準備を済ませたら、町から北へ出る東の道で我々と合流してくれ。出発前に、全員と最後の確認を1回行う。", nil, nil, 0x5db1f556, 0xd94373fd, 0x8619e90a, nil, nil, "...mm" },
  [93089] = { "この先に待つもの", "Zephras Isleを発つ準備ができたら、Elaadrin Evengaleと話してください。", "Elaadrinに、High Orderと、君の新しい友である「Kirin Tor」がZephras Isleのためにしてくれたすべてのことへの感謝を伝えてほしい。High Orderが島を離れる計画は承知している。君たちの結社のこの遠征には、私の祝福と幸運の祈りがある。\n\nHigh Orderが見つける秘術の解決策が何であれ、ここ数年我々に欠けていた安定を本当にもたらしてくれることを願うばかりだ。君も彼らと行くつもりなら……まあ、彼の使命はそれだけ力強いものになるだろう。\n\n風が共にあらんことを、{name}。", nil, nil, 0x50a257df, 0xb2d66ffb, 0x327a8719, nil, nil, "...mm" },
  [93090] = { "この先に待つもの", "Zephras Isleを発つ準備ができたら、Ayessa Dawnsingerと話してください。", "Ayessaに、Windshapersと、君の新しい友である「Earthen Ring」がZephras Isleのためにしてくれたすべてのことへの感謝を伝えてほしい。Windshapersのシャーマンたちを連れて島を離れる計画は承知している。君たちの結社のこの遠征には、私の祝福と幸運の祈りがある。\n\nWindshapersが見つける解決策が何であれ、ここ数年我々に欠けていた安定を本当にもたらしてくれることを願うばかりだ。\n\n風が共にあらんことを、{name}。", nil, nil, 0x50a257df, 0x42ef0bb4, 0x0c8b4884, nil, nil, "..smm" },
  [93159] = { "奇妙な隠者", "Shadowgale ForestのStrange Hermitと話し、彼についてもっと知ってください。", "あ、えっと……こ、こんにちは、じゃなくて、やあ！ ご機嫌よう、とか！ ごめんなさい……その、えっと、誰かと実際に話すのは本当に久しぶりで。ちょっと慣れてなくて。\n\n<奇妙なフードの人物が、あなたの前で落ち着かなげに身じろぎする。>\n\nそれで、えっと、その……今日はどんな一日ですか？", nil, nil, 0xc281d56b, 0x91510117, 0x0eddd708, nil, nil, "..smm" },
  [93160] = { "森の恵み", "Shadowgale ForestでShadowgale Acornを$N1個集めてください。", "話しに寄ってくれて本当に嬉しいです！ も、もし手伝ってくれるなら、森の地面からどんぐりを集めるのを少し手伝ってほしいんです。近くのはほとんど集めたんですけど、森にはraptorみたいな鳥がすごくたくさんいて。外は危ないし、巨大な鳥のお昼ごはんにはなりたくないんです！\n\nだから、もしよかったら、集めてきてもらえませんか？ そうしてくれたら、何かおいしいものを作りますね！", nil, nil, 0x4aa75777, 0x076dacd0, 0xb98c76cc, nil, nil, "...mm" },
  [93165] = { "慈悲は聞く耳を持たぬ者に", "Shadowgale Forest、Shrine of Akir、またはGustberry LowlandsのAl'Aketh信者から、Al'Aketh Cultist's Earsを10個集めて下さい。", "Al'Akethは我らの集落に大いなる悲劇をもたらした。血は血で償わせねばならぬ。\n\nよそ者よ、そなたに申し出がある。この呪われた教団員どもと争うことがあれば、倒した者の耳を持ってくるがよい。持ち帰った耳ごとに金で報いよう。そして、そなたが真の友であると証明すれば、いずれNightclawの秘密に触れることも許そう。", nil, nil, 0x67167132, 0x39b5cde8, 0xf3604d96, nil, nil, "...mm" },
  [93172] = { "Hollowsの解放", "Shadowgale ForestのWind Hollowsを10個破壊してください。", "この島のelvesのほとんどは、この森には幽霊が出ると思っているみたいだし、それは間違いじゃない。\n\n北東の古い遺跡には、幽霊のような奇妙な精霊が集まるんだ。夜によっては、彼らが「歌っている」のが聞こえそうなほどだよ。今まで聞いたどんな歌とも違うけど、確かに歌で、それが……ただただ悲しいんだ。\n\nなぜかは分からないけど、いつかあそこで何か恐ろしいことが起きて、精霊たちはどういうわけかそこに閉じ込められているんだと思う。勇気があるなら、彼らを解放してあげられないかな？", nil, nil, 0x0e18dc30, 0x1267d2ac, 0xc486b74c, nil, nil, "..smm" },
  [93173] = { "（未使用）Rusty Gadget", "Shadowgale ForestのThe Strange HermitにRusty Gadgetを返して下さい。", "<Wind Hollowをまとめていた渦巻く気流が消えはじめると、小さな金属の装置が足元に転がり落ちた。何かの機械仕掛けの道具のようだ。The Strange Hermitはまだ装備がいくつか見つかっていないと言っていた。これに興味を持つかもしれない。>", nil, nil, 0xd8c783cf, 0x333107c8, 0xd88d703f, nil, nil, "...mm" },
  [93317] = { "カニの季節", "Windsong Crawler Meatを6つ集めてください。", "Windsong Crawlersをご存じですか？ このカニはここZephrasのWindsong Lakeにしかいなくて、一年のうち数週間しか獲れないんです。\n\n最近の教団の活動のせいで湖まで獲りに行けなくて、時期がどんどん終わりに近づいています。行って少し集めてきてくれたらありがたいです。たいてい湖の周りの岸辺や川沿いにいます。\n\nでも気をつけてくださいね、見た目より凶暴ですから！", nil, nil, 0x6f40d8c7, 0x3826218b, 0xb3597e4b, nil, nil, "...mm" },
  [93318] = { "お尋ね者：Vulgara the Insatiable", "Shen'dar HighlandsでVulgara the Insatiableを倒し、その首をDanarii Bellowveilに届けてください。", "PeacekeepersのConstable Aondaの命により、ここに高地の災厄、Vulgara the Insatiableに懸賞金をかける。最後に目撃されたのはShen'dar Villageのすぐ南西の丘の上。翼を持つこのvuldrenの怪物は非常に危険であり、慎重に近づくこと。\n\n報酬を受け取るには、その獣の首をDanarii Bellowveilに届けること。", nil, nil, 0x26deadde, 0x95335eb7, 0x44a54b33, nil, nil, "...mm" },
  [93319] = { "Pilfered Windstones", "Shen'dar HighlandsのHighlands Banditsから、Pilfered Windstonesを10個集めてください。", "ここZephrasでは日々の暮らしでwindstonesにますます頼るようになっているから、非常時に備えて蓄えを保つようにしているんだ。ところが最近、倉庫からいくつかなくなっているのに気づいた。\n\n最近捕まえた山賊がwindstonesを持っていたから、不足の原因は奴らだと睨んでいる。\n\n北の山賊の洞窟の近くに行くことがあったら、何人か叩きのめして、盗まれたwindstonesを取り返してきてくれないか？", nil, nil, 0x41d7b2ca, 0x098aea7b, 0x92a811d5, nil, nil, "..smm" },
  [93320] = { "塔の防衛", "Gustberry Lowlandsの東の見張り塔にいるYorana Windyreedに報告してください。", "町のすぐ外にあるパイロンの見張り塔を教団が攻撃しているという知らせが入った！ ここにいる数少ない予備の治安維持隊を送り、敵の後方線を突破して守備隊を救援させようとしているが、少しでも助けが増えれば、あそこにいる仲間たちの生死を分けるかもしれない。\n\nすぐに東の見張り塔へ向かい、できる限りの援護をしてくれ。\n\n救援部隊は私の副官Yorana Windyreedが率いている。彼女がまだ生きていれば、どう助けるのが最善か教えてくれるだろう。", nil, nil, 0x0a49deab, 0x7f44b2b4, 0x98ee9961, nil, nil, "...mm" },
  [93459] = { "さらなるAl'Akethの耳", "Shadowgale Forest、Shine of Akir、またはGustberry LowlandsにいるAl'Akethから、Al'Aketh Cultist's Earsを10個集め、Shadowgale ForestのVayn Moonclawに届けてください。", "Al'Aketh cultは普段、この森に幽霊が出るという噂を恐れて近づかない……その噂は我々が喜んで保っているものだ。我が結社のドルイドたちは、ここShadowgaleで静かで平和な暮らしを望んでいるだけなのに、奴らはそれを脅かしている。\n\n我々の多くが恐れている。\n\n申し出がある。我々の代わりに教団員と戦い、倒した者の耳を持ってきてくれ。持ち帰った耳ごとに金で報いよう。そして、君が真の友であると証明すれば、いずれ我々の秘密に触れることも許そう。", nil, nil, 0x91339b63, 0x4cc2e33c, 0x184326a2, nil, nil, "...mm" },
  [93461] = { "Shen'dar Villageへようこそ", "Shen'dar VillageのRathiril SunlanceとCoriella Calmbreezeと話してください。", "君には「High Order」の雰囲気があるね。Highborneの血を引く者は、いつも目に少しきらめきがあるから分かるんだ。ここで本格的に働いてもらう前に、ここに住むHigh Orderの長老、Rathiril Sunlanceに挨拶しておくといい。ここ本館の、私のすぐ角を曲がった所にいるよ。\n\nああ、それとCoriella Calmbreezeにも顔を出しておいて。地元の宿屋をやっていて、必要なら宿と物資を用意してくれる。", nil, nil, 0x4c9d3c02, 0xe867665b, 0x8517821c, nil, nil, "...mm" },
  [93552] = { "Windstonesの採取", "Thendal GroveのRaw Windstonesから、Windstone Clustersを15個集めてください。", "WindstonesはZephras Isleにとって欠かせない資源だ。風そのものの生の凝縮されたエネルギーが込められているからね。かつてここZephrasで我々と共に暮らしていた風の精霊たちは数世紀前に姿を消し、それ以来、この島を支える魔法はゆっくりと薄れつつある。限界はあるものの、windstonesは今も頼れるエネルギー源で、我々にとって非常に貴重なんだ。\n\n森のあちこちに生のwindstonesが散らばっている。採集を手伝ってくれないか？", nil, nil, 0x2bcfca6e, 0xe8cd67c8, 0x2a09472f, nil, nil, "..smm" },
  [93735] = { "壊れた構築体", "Valanaarの西側でRiaani Nightwindを見つけてください。", "歴史的に、Windshapersは風の精霊から授けられた魔法の器具や装置の手入れを担ってきました。島中にある無数の魔法の構造体もそうです。精霊たちが去って以来、そのうちまだ動くのはごくわずかです。\n\nValanaarでまだ動く数少ない構造体の一つが損傷してしまいました。職人の一人を助けに向かわせましたが、彼には手助けが必要かもしれません。街の西の端へ行き、できる限りの援助をしてください。", nil, nil, 0x3b580ff6, 0xb230d6e2, 0x9c9b9f2d, nil, nil, "...mm" },
  [93736] = { "招かれざる霊", "Shadowgale ForestのWind Hollowsから、Wind Hollow Essencesを10個集めてください。", "Windshapersの最大の関心事は、精霊たちがなぜ我々のもとを去ったのか、そして彼らを連れ戻すために何ができるのかを、よりよく理解することです。北のShadowgale Forestの奇妙な特徴の一つに、「hollows」と呼ばれる不思議な風の精がいることがあります。彼らについても、なぜそこにいるのかについてもほとんど分かっていませんが、風の精霊が去った後に初めて現れ始めたことは分かっています。\n\nそこへ行き、彼らを散らしてください。その残骸を集めて、ここへ持ってきてください。", nil, nil, 0x4f4a02b2, 0x24071ed5, 0x120ac132, nil, nil, "...mm" },
  [93737] = { "壊れた構築体", "Riaani Nightwindと話し、彼の話を聞いて下さい。", "ああ、どうも。Ayessaが手伝いによこしたって？ それならいいか。\n\n君みたいな見るからに素人に何ができるか分からないが、この構造体の中身から頭を引っこ抜くまで少し待ってくれれば、手伝ってもらえそうなことをいくつか思いつくかもしれない。", nil, nil, 0x3b580ff6, 0x20bf5d1d, 0xc9fcddd9, nil, nil, "...mm" },
  [93738] = { "壊れた構築体", "ValanaarのAyessa Dawnsingerのところへ戻って報告してください。", "Brightwish、だって？ つまりHigh Orderは何かの理由でこの部品を取り外したかったわけか。でも、なぜだ？\n\nHigh Orderは昔からおせっかいで、しょっちゅう風の精霊の魔法で実験したがる。とんでもなく大胆すぎるんだ。だからWindshaperの管轄下にある知識に手を出すことは固く禁じてきたんだが、最近は我々の我慢を試すような真似をしている。\n\n分かったことをAyessa Dawnsingerに報告したほうがいい。次に何をすべきか指示してくれるだろう。", nil, nil, 0x3b580ff6, 0x29d7b548, 0xbeae1a55, nil, nil, "..smm" },
  [93739] = { "Hordeを探る", "Grommash HoldのNazgrelと話し、さらなる指示を受けてください。受けた指示に従って、Vol'jin、Cairne Bloodhoof、Lady Sylvanas Windrunnerを探し出して話してください。", "Azerothは広大な世界であり、Hordeの領土も広い。Undercity、Orgrimmar、Thunder Bluffには、それぞれ非常に独特な民と文化がある。\n\nここAzerothでhordeの客人となるなら、我らの首都を順に訪ねるとよいだろう。道は私の相談役、Nazgrelに聞くといい。", nil, nil, 0x7968676a, 0x9721d08e, 0x637f703e, nil, nil, "..smm" },
  [93740] = { "血には血を", "Gustberry LowlandsのAl'Akethの信者の死体から、Al'Aketh Windstone Charmsを10個集めてください。", "今朝、Windshaperの見習いたちが何人もHighlandsで死んでいるのが見つかった。確かなことは言えないが、Al'Akethの仕業である可能性が高い。Windshapersは、血には血で報いる。必ずだ。\n\n北へ向かい、出会ったAl'Akethを片っ端から倒せ。その証として、奴らのwindstone prayer charmsを持ってこい。我々は許さないし、忘れない。", nil, nil, 0x8fdc4a0a, 0xc45880fd, 0xe1adb7e7, nil, nil, "...mm" },
  [93746] = { "断固たる対応", "Shrine of Akirへ向かう道沿いでBelathaan Brightwishと対決して下さい。", "High Orderには、Windshaperの問題に首を突っ込めばどうなるか警告してある。Belathaanを見せしめにして、いくつか痣をつけて、我々の定めた境界への健全な敬意を植え付けたうえでHigh Orderへ送り返すべきだと思う。\n\nBelathaanは町を出て、北のShrine of Akirへ向かうところを見られている。なぜそこへ向かったのかは分からないが、道中で一人のところを問い詰めるのが最も安全だ。彼を見つけて、心に少し恐怖を植え付けてやれ。", nil, nil, 0x2e10a415, 0x87bb368c, 0x049e9393, nil, nil, "...mm" },
  [93791] = { "Belannとの対話", "ValanaarのBelann Windwoodと話してください。", "{name}、あなたの魔法の腕が上がっているのは明らかです。若く志あるメイジのための、High Orderの最も古い伝統の一つに参加する時が来たと思います。あなた自身の呪文の触媒を作る時です。\n\nValanaarのBelann Windwoodを訪ねてください。彼は一世紀以上もHigh Orderのために杖やワンドを作ってきましたから、安心して任せられます。", nil, nil, 0x9eee1307, 0xdac9b99f, 0x9e12128a, nil, nil, "...mm" },
  [93797] = { "風に揺れる枝", "Wind-Infused BoughをValanaarのBelann Windwoodに届けてください。", "ある程度の魔法の熟練を示した若いメイジが、自分自身の呪文の触媒を作るのは、昔ながらの伝統だ。これは普通、我らの最も古い木々から落ちた枝を集めて行う。そうした木々には風の元素の痕跡がわずかに残っているからね。\n\n最も理想的な枝は、Falaath Villageのすぐ南にある風の祠の近くにあると分かった。行って大きな枝を持ってきてくれれば、君の呪文の触媒を作りながら伝統について教えよう。", nil, nil, 0x53b7cabb, 0xbb3c4f26, 0x55b3e7d7, nil, nil, "...mm" },
  [93835] = { "Lorthunaとの対決", "頭上のRohashi Spiresへ通じるポータルを使い、High Priestess Lorthunaと対峙するElaadrin EvengaleとAyessa Dawnsingerに加わってください。", "Lorthunaは何かのポータルを使って上の尖塔へ逃げた。AyessaとElaadrinが後を追って入っていった。ほんの少し前のことだ。\n\nすまないが、攻撃を1発多く食らいすぎた。私はここまでだ。ポータルを抜けて、Elaadrinを見つけ、彼らがLorthunaを止めるのを手伝ってくれ。\n\nElaadrinとAyessaが呼んだという援軍がすぐに来ない限り、ここからは君一人だ。幸運を、{class}。", nil, nil, 0x90290d9d, 0x21f66bcc, 0xcf4192f2, nil, nil, "...mm" },
  [93836] = { "Zephrasの運命", "ValanaarのTalaanis Shadowsongと話してください。", "Mulnはエレメンタルの王たちについて多くを語ってくれたが、我々にはAl'Akirを恐れるだけの十分な理由があるようだ。Zephrasを彼の目から隠していた結界が消えた今、我々はまったくの無防備だ。彼が攻撃してくると決めたなら、彼自身の領域であるここでは、我々に勝ち目はない。\n\nHigh Elder Shadowsongは、我々が置かれている危険と、何より、Azerothへの任務における我々の意図を知る必要がある。我々は故郷を救う手立てを見つけ出す。誓おう。", nil, nil, 0x6d3ea2fe, 0x4440ff8a, 0x7c6d6603, nil, nil, "...mm" },
  [93862] = { "木箱の返却", nil, nil, nil, nil, 0xeb410c2b, nil, nil, nil, nil, ".mmmm" },
  [93926] = { "西の見張り", "西の見張り塔でPeacekeeper Vaanielを見つけてください。", "教団が塔を攻撃する理由が何であれ、仲間を失うほどの価値はない。\n\n南西へ向かって、あの見張り塔の様子を見てきてくれ。そこにいる治安維持隊を見つけて、村へ戻るよう伝えるんだ。あの塔を守るのは、それで失われる命に見合わない。それより、ここにいる守備兵を集めて住民を守りたい。\n\n指揮を執っているのはPeacekeeper Vaanielだ。できるだけ早くここへ戻るよう伝えてくれ。急げ！", nil, nil, 0x18869d4a, 0xc19f2264, 0x907a6889, nil, nil, "..smm" },
  [93927] = { "最後の頼み", "死んだ平和維持官のそばで見つけた書き付けを拾い、それを読んで次にすべきことを決めてください。", "<死んだ治安維持隊員の遺体を調べていると、血に濡れたメモがその手から落ちた。拾って読めば、ここからどうすべきか手がかりが得られるかもしれない。>", nil, nil, 0x96fa8046, 0xf1e8b9e6, 0xc18d4d9f, nil, nil, "...mm" },
  [93928] = { "ネズミとミルク", "ネズミにクッキーを取ってきてあげてください。", "クッキーがほしいんだ、分かるか？\n\nへっ！", nil, nil, 0x4a4cc954, 0xaadb1f71, 0xe2b329a9, nil, nil, "...mm" },
  [93948] = { "印章の配達", "Shadowsong Family SignetをValanaarのTalaanis Shadowsongに届けてください。", "どうせValanaarへ行くのなら、塔で取り戻した印章指輪をValanaarのTalaanis Shadowsongに届けてください。\n\n彼はこれを取り戻したいでしょうし、何より、甥の身に何があったのか知りたいはずです。TalaanisはZephras IsleのHigh Elderであり、何より、今の苦難にもかかわらず民に深く愛されている善き人です。この知らせに彼がどう反応するかを思うと胸が痛みます。彼の喪失にお悔やみを伝えてください。", nil, nil, 0x95398690, 0x57f7b4b1, 0xba89a78d, nil, nil, "...mm" },
  [93949] = { "虫にやられて", "ValanaarでSkyhopperを倒し、Enchanted Skyhopperを$N1体始末する。", "盗聴されていたんだ。\n\n低地は今skyhopperの季節で、つまりそこら中にこの害虫がいる。High Orderのメイジの一人が、倒した虫の一匹に何かの付呪がかけられていたと報告してきた。よく調べてみると、盗み聞きの呪文の一種らしい。\n\n教団がこの付呪された虫を密偵として使っているのではないかと我々は疑っている。行って駆除してきてくれ。見た目ではどれが付呪されているか分からないから、全部倒すしかない。", nil, nil, 0xebc83872, 0xf0db79e8, 0x5a7063fe, nil, nil, "...mm" },
  [93951] = { "ささやかな美", "Shen'dar HighlandsでHippogryph Downの羽根を8枚集めてください。", "村の南西に住み着いたHippogryphは厄介なこともあるけど、その羽根を手に入れるまたとない機会でもあるんだ。多くのskyborneは鮮やかな羽根で髪を飾るのが大好きで、hippogryphのdown feathersは格別に鮮やかで、何より絹のように柔らかい。\n\nそっちへ行くなら、巣の中や周りに落ちている羽根をできるだけ集めてきて。気をつけてね、野生のhippogryphは客を歓迎しないから。", nil, nil, 0xfb24871b, 0xf83626f8, 0x902313cc, nil, nil, "..smm" },
  [93958] = { "奥の聖域", "Shrine of Akirの内陣にいるValennia Stormfistと話してください。", "Valenniaの部隊がたった今、内なる聖域に突入した。最初は中で激しい戦いになっていたが、今は……不気味なほど静かになった。中へ入って、Valenniaと彼女の部隊に合流できるよう最善を尽くしてくれ……まだ誰か残っていればだが。\n\n私はここに残って、君の背後を守る。", nil, nil, 0x757fc20c, 0xb9c9ad7e, 0xfe6de4be, nil, nil, "...mm" },
  [93963] = { "Allianceを探る", "Stormwind KeepのRandal Emersonと話し、さらなる指示を受けてください。受けた指示に従って、King Magni Bronzebeard、High Tinker Mekkatorque、Tyrande Whisperwindを探し出して話してください。", "Stormwind、Ironforge、Darnassusには、それぞれ独自の民と文化があります。ここAzerothのAllianceの客人として、我々の首都を順に訪ねる時間を取るとよいでしょう。\n\nまずは南の控えの間にいるRandal Emersonに道を聞いてください。", nil, nil, 0xb5c2bf15, 0x80cbe7b7, 0x7db457d1, nil, nil, "...mm" },
})
